    // ===================== Settings =====================
    var appSettings = loadJSON('jlptSettings', {});
    if (!appSettings || typeof appSettings !== 'object') appSettings = {};
    // Default auto-next to off on first launch of this version, including existing installations.
    // Subsequent user changes are respected.
    if (!appSettings.autoNextOffDefaultApplied) {
        appSettings.autoNext = false;
        appSettings.autoNextOffDefaultApplied = true;
        try { localStorage.setItem('jlptSettings', JSON.stringify(appSettings)); } catch (e) {}
    }
    // the おみくじ is always printed 縦書き now: the old 縦書き／横書き choice is wiped from saved settings
    if (appSettings && 'omikujiDir' in appSettings) { delete appSettings.omikujiDir; try { localStorage.setItem('jlptSettings', JSON.stringify(appSettings)); } catch (e) {} }
    function getSetting(k, def) { return appSettings[k] !== undefined ? appSettings[k] : def; }
    function setSetting(k, v) { appSettings[k] = v; localStorage.setItem('jlptSettings', JSON.stringify(appSettings)); }

    var darkQuery = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
    function applyTheme() {
        var t = getSetting('theme', 'auto');
        var dark = t === 'dark' || (t === 'auto' && darkQuery && darkQuery.matches);
        document.documentElement.classList.toggle('dark', !!dark);
        var meta = document.querySelector('meta[name="theme-color"]');
        if (meta) meta.setAttribute('content', dark ? '#16181c' : '#ffffff');
    }
    if (darkQuery) {
        var onScheme = function() { if (getSetting('theme', 'auto') === 'auto') applyTheme(); };
        if (darkQuery.addEventListener) darkQuery.addEventListener('change', onScheme); else if (darkQuery.addListener) darkQuery.addListener(onScheme);
    }
    applyTheme();

    function markSeg(id, value) {
        document.querySelectorAll('#' + id + ' button').forEach(function(b) { b.classList.toggle('active', b.dataset.v === String(value)); });
    }

