        var c = dictCandidates(word);
        if (!c.length) return null;
        var map = readingMap();
        var known = function(w) { return !!(wordDefinitions[w] || map[w] || readingCache[w] || wordList.some(function(e) { return e.word === w; })); };
        c.forEach(function(x, i) { x.i = i; });
        c.sort(function(a, b) { return (known(b.w) - known(a.w)) || (a.p - b.p) || (a.i - b.i); });
