    // older callers
    function wqDone(stats, note, again) { wqResult({ title: 'おつかれさまでした', pct: 100, chips: [], note: stats + (note ? '<br>' + note : ''), again: again }); }
    // 四択 settings (remembered): kind of question, how many, and how many choices
