        if (i < 0) return safe;
        var first = wq.opts.hint === 'first', rest = it.e.word.length - (first ? 1 : 0), pick = !!(it.opts || it.bank);
        // 書く: the input sits in the blank itself; with the 最初の字 hint that character is already there
        var mid = filled ? '<mark class="cloze-fill ' + (right ? 'ok' : 'ng') + '">' + w + '</mark>'
            : '<span class="cloze-blank' + (pick ? '' : ' typing') + '"' + (pick ? ' style="min-width:' + Math.max(2.2, it.e.word.length * 1.05) + 'em"' : '') + '>' +
                (first ? '<span class="cloze-first">' + escapeHtml(it.e.word.charAt(0)) + '</span>' : pick ? '&#8203;' : '') +
                (pick ? '' : '<input class="cloze-inline" id="cloze-input" lang="ja" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="空欄に入る言葉" style="width:' + Math.max(2.4, rest * 1.15 + 0.8) + 'em">') + '</span>';
        return safe.slice(0, i) + mid + safe.slice(i + w.length);
