            (label ? '<div class="wq-dir">' + escapeHtml(label) + '</div>' : '') +
            '<div class="cloze-sentence">' + clozeSentence(it, done, done && a.right) + '</div>' +
            (!done && hint === 'meaning' && wqMeaning(e) ? '<div class="cloze-hint"><small>意味</small>' + escapeHtml(wqClip(wqMeaning(e), 90)) + '</div>' : '');
