    function renderWordListItems() {
        var content = document.getElementById('wordlist-content');
        var tabCount = document.querySelector('button[data-sub="words"] .count');
        if (tabCount) tabCount.textContent = wordList.length;
        content.classList.toggle('hide-furigana', !!getSetting('wlHideFurigana', false));
        updateWordListTools();
        if (!wordList.length) {
            document.getElementById('wordlist-count').textContent = '0語';
            content.innerHTML = '<div class="empty-bookmarks">単語帳は空です。<br>問題の中の単語を長押しすると追加できます。</div>';
            return;
        }
        var items = wordList.filter(wordMatchesFilters);
        document.getElementById('wordlist-count').textContent = items.length === wordList.length ? wordList.length + '語' : items.length + ' / ' + wordList.length + '語';
        if (!items.length) {
            content.innerHTML = '<div class="empty-bookmarks">条件に合う単語はありません。</div>';
            return;
        }
        if (currentWordSort === 'kana') items.sort(function(a, b) { return a.word.localeCompare(b.word, 'ja'); });
        else items.sort(function(a, b) { return b.added - a.added; });
        content.innerHTML = items.map(function(e, i) {
            var d = new Date(e.added);
            return '<div class="word-item" data-id="' + e.id + '">' +
                '<div class="word-item-word"><span class="word-item-no" aria-hidden="true">' + (i + 1) + '</span>' + entryWordHtml(e) + '<button class="word-item-speak" aria-label="「' + escapeHtml(e.word) + '」を読み上げ" title="読み上げ">🔊</button>' + (isLearned(e) ? '<span class="word-learned" title="カードで3回続けて覚えた">覚えた</span>' : '') + '</div>' +
                '<div class="word-item-meaning' + (e.meaning ? '' : ' empty') + '">' + (e.meaning ? escapeHtml(e.meaning) : 'タップして意味・メモを追加') + '</div>' +
                '<div class="word-item-def' + (e.writeDef ? '' : ' empty') + '">' + (e.writeDef ? '<b>書く練習</b>' + escapeHtml(e.writeDef) : '✎ タップして書く練習の定義を追加') + '</div>' +
                (e.context ? '<div class="word-item-context">' + highlightIn(e.context, e.word) + '</div>' : '') +
                '<div class="word-item-meta"><span>' + (textbookLabel(e.qid) ? '<b class="word-item-qnum">' + escapeHtml(textbookLabel(e.qid)) + '</b>' : escapeHtml(e.source || '')) + (e.qid || e.source ? '・' : '') + d.getFullYear() + '/' + (d.getMonth() + 1) + '/' + d.getDate() + '</span>' +
                (e.qid && findQuestion(e.qid) ? '<button class="word-item-open" data-qid="' + e.qid + '">問題を見る</button>' : '') + '</div>' +
                (e.others || []).map(function(o) {           // the other sentences and places this word was found in
                    var lab = textbookLabel(o.qid) ? '<b class="word-item-qnum">' + escapeHtml(textbookLabel(o.qid)) + '</b>' : escapeHtml(o.source || (o.qid && findQuestion(o.qid) ? qWhere(findQuestion(o.qid), '') : ''));
                    return '<div class="word-item-more">' + (o.context ? '<div class="word-item-context">' + highlightIn(o.context, e.word) + '</div>' : '') +
                        '<div class="word-item-meta"><span>' + lab + '</span>' + (o.qid && findQuestion(o.qid) ? '<button class="word-item-open" data-qid="' + o.qid + '">問題を見る</button>' : '') + '</div></div>';
                }).join('') +
                '<div class="dict-row word-item-dicts">' + dictButtonsHtml() + '</div>' +
                '<button class="word-item-delete" data-id="' + e.id + '" aria-label="削除">×</button>' +
                '</div>';
        }).join('');
        content.querySelectorAll('.word-item').forEach(function(el) {
            el.addEventListener('click', function(ev) {
                if (ev.target.closest('.word-item-delete, .word-item-open, .dict-row')) return;
                var entry = wordList.find(function(w) { return w.id === el.dataset.id; });
                if (entry) openWordSheet({ word: entry.furigana || entry.word, context: entry.context, qid: entry.qid, editId: entry.id });
            });
        });
        content.querySelectorAll('.word-item-delete').forEach(function(btn) {
            btn.addEventListener('click', function(ev) {
                ev.stopPropagation();
                var entry = wordList.find(function(w) { return w.id === btn.dataset.id; });
                showConfirm('単語を削除', '「' + (entry ? entry.word : '') + '」を単語帳から削除しますか？', '削除する', true, function() {
                    var undoBefore = wordBegin();
                    wordList = wordList.filter(function(w) { return w.id !== btn.dataset.id; });
                    saveWordList();
                    wordCommit(undoBefore, '「' + (entry ? entry.word : '') + '」を削除');
                    renderWordListItems();
                });
            });
        });
        setTimeout(fillMissingReadings, 0);
        // 🔊 reads the word only (its reading when known, so kanji aren't misread), never the メモ
        content.querySelectorAll('.word-item-speak').forEach(function(btn) {
            btn.addEventListener('click', function(ev) {
                ev.stopPropagation();
                var entry = wordList.find(function(w) { return w.id === btn.closest('.word-item').dataset.id; });
                if (entry) speakText(escapeHtml(entry.reading || entry.word));
            });
        });
        content.querySelectorAll('.word-item-dicts .dict-btn').forEach(function(btn) {
            btn.addEventListener('click', function(ev) {
                ev.stopPropagation();
                var entry = wordList.find(function(w) { return w.id === btn.closest('.word-item').dataset.id; });
                if (entry) openDictionary(btn.dataset.dict, entry.word, entry.id);
            });
        });
        content.querySelectorAll('.word-item-open').forEach(function(btn) {
            btn.addEventListener('click', function(ev) {
                ev.stopPropagation();
                var qid = parseInt(btn.dataset.qid, 10);
                var entry = wordList.find(function(w) { return w.id === btn.closest('.word-item').dataset.id; });
                wordHighlight = entry ? { qid: qid, word: entry.word, scrolled: false } : null;
                pendingOrigin = 'review'; pendingTitle = '問題を見る';
                startListQuiz([qid], qid, false, 'practice');
            });
        });
    }

