    // ===================== Backup & restore =====================
    var BACKUP_REMIND_DAYS = 7;
    // Home card: shown once there is something worth saving and the last backup is a week old (or there is none).
    // 「あとで」 hides it for 3 days.
    function backupReminderHtml() {
        var hasData = attemptLog.length >= 10 || wordList.length >= 3;
        if (!hasData) return '';
        var snooze = parseInt(localStorage.getItem('jlptBackupSnooze'), 10);
        if (snooze && Date.now() < snooze) return '';
        var last = parseInt(localStorage.getItem('jlptLastBackup'), 10);
        var days = last ? Math.floor((Date.now() - last) / 86400000) : null;
        if (last && days < BACKUP_REMIND_DAYS) return '';
        return '<div class="home-backup" id="home-backup">' +
            '<div class="home-backup-text"><b>' + (last ? '前回のバックアップから' + days + '日たちました' : 'バックアップをとりましょう') + '</b>' +
            '単語帳' + (wordList.length ? '（' + wordList.length + '語）' : '') + '・成績・メモは、この端末のブラウザの中にだけ保存されています。</div>' +
            '<div class="home-backup-actions"><button id="home-backup-later">あとで</button><button id="home-backup-save" class="primary">保存する</button></div></div>';
    }
    function bindBackupReminder() {
        var save = document.getElementById('home-backup-save');
        if (!save) return;
        save.addEventListener('click', saveBackupFile);
        document.getElementById('home-backup-later').addEventListener('click', function() {
            try { localStorage.setItem('jlptBackupSnooze', String(Date.now() + 3 * 86400000)); } catch (e) {}
            var card = document.getElementById('home-backup');
            if (card) card.remove();
            showToast('3日後にまたお知らせします');
        });
    }

    function buildBackupJson() {
        saveTime();
        var data = {};
        Object.keys(localStorage).forEach(function(k) {
            if (k.indexOf('jlpt') === 0 && k !== 'jlptLastBackup' && k !== 'jlptBackupSnooze') data[k] = localStorage.getItem(k);
        });
        return JSON.stringify({ app: 'mogi', format: 1, exportedAt: new Date().toISOString(), data: data });
    }

    function markBackedUp() {
        localStorage.setItem('jlptLastBackup', String(Date.now()));
        localStorage.removeItem('jlptBackupSnooze');
        var card = document.getElementById('home-backup');
        if (card) card.remove();
        updateBackupStatus();
    }

    function updateBackupStatus() {
        var el = document.getElementById('backup-status');
        if (!el) return;
        var last = parseInt(localStorage.getItem('jlptLastBackup'), 10);
        var hasData = attemptLog.length > 0 || Object.keys(reportAnswers).length > 0 || wordList.length > 0;
        if (!last) {
            el.innerHTML = '前回のバックアップ：<b>なし</b>' + (hasData ? '　<span class="backup-warning">まだ一度も保存していません</span>' : '');
            return;
        }
        var d = new Date(last);
        var days = Math.floor((Date.now() - last) / 86400000);
        el.innerHTML = '前回のバックアップ：<b>' + d.getFullYear() + '/' + (d.getMonth() + 1) + '/' + d.getDate() + '</b>（' + (days === 0 ? '今日' : days + '日前') + '）' +
            (days >= BACKUP_REMIND_DAYS && hasData ? '　<span class="backup-warning">そろそろ保存しましょう</span>' : '');
    }

    function showTextDialog(title, message, text, okLabel, onOk, readOnly) {
        var overlay = document.getElementById('text-overlay');
        var area = document.getElementById('text-area');
        var okBtn = document.getElementById('text-ok');
        var cancelBtn = document.getElementById('text-cancel');
        document.getElementById('text-title').textContent = title;
        document.getElementById('text-message').textContent = message;
        area.value = text || '';
        area.readOnly = !!readOnly;
        okBtn.textContent = okLabel;
        overlay.classList.add('active');
        var close = function() { overlay.classList.remove('active'); okBtn.onclick = null; cancelBtn.onclick = null; };
        okBtn.onclick = function() { onOk(area.value, close); };
        cancelBtn.onclick = close;
        if (readOnly) { area.focus(); area.select(); } else { area.focus(); }
    }

    function saveBackupFile() {
        var json = buildBackupJson();
        var d = new Date();
        var name = 'mogi-backup-' + d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0') + '.json';
        try {
            saveTextFile(name, 'application/json', json, function(ok, cancelled) {
                if (cancelled) return;
                if (!ok) { copyBackupText(); return; }
                markBackedUp();
                showConfirm('バックアップを保存しました', IN_ANDROID_APP ? '「' + name + '」を保存しました。' : '「' + name + '」をダウンロードしました。\nファイルが見つからない場合は「テキストでコピー」を使ってください。', 'OK', false, function() {});
                document.getElementById('confirm-cancel').style.display = 'none';
            });
        } catch (e) {
            copyBackupText();
        }
    }

    function copyBackupText() {
        var json = buildBackupJson();
        showTextDialog('バックアップ（テキスト）', '下のテキストをすべてコピーして、メモアプリなどに保存してください。復元するときは「テキストから復元」に貼り付けます。', json, 'コピー', function(value, close) {
            var area = document.getElementById('text-area');
            var done = function() {
                markBackedUp();
                document.getElementById('text-ok').textContent = 'コピーしました ✓';
            };
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(value).then(done, function() {
                    area.select();
                    try { if (document.execCommand('copy')) done(); } catch (e) {}
                });
            } else {
                area.select();
                try { if (document.execCommand('copy')) done(); } catch (e) {}
            }
        }, true);
    }

    function parseBackup(text) {
        var obj;
        try { obj = JSON.parse(text); } catch (e) { return { error: 'バックアップの形式が正しくありません（JSONとして読み込めません）。' }; }
        if (!obj || obj.app !== 'mogi' || typeof obj.data !== 'object' || !obj.data) return { error: 'モギのバックアップではありません。' };
        var keys = Object.keys(obj.data);
        if (!keys.length) return { error: 'バックアップにデータが入っていません。' };
        for (var i = 0; i < keys.length; i++) {
            if (keys[i].indexOf('jlpt') !== 0 || typeof obj.data[keys[i]] !== 'string') return { error: 'バックアップに不正なデータが含まれています。' };
            try { JSON.parse(obj.data[keys[i]]); } catch (e) {
                if (!/^[\w.-]*$/.test(obj.data[keys[i]])) return { error: 'バックアップの一部が壊れています（' + keys[i] + '）。' };
            }
        }
        return { backup: obj };
    }

    function summarizeBackup(obj) {
        var get = function(k, fallback) { try { return JSON.parse(obj.data[k]); } catch (e) { return fallback; } };
        var answers = Object.keys(get('jlptUserAnswers', {}) || {}).length;
        var daily = get('jlptDaily', {}) || {};
        var days = Object.keys(daily).filter(function(k) { return daily[k] && daily[k].answered > 0; }).length;
        var bookmarks = (get('jlptBookmarks', []) || []).length;
        var when = obj.exportedAt ? new Date(obj.exportedAt) : null;
        return (when && !isNaN(when) ? '保存日時：' + when.getFullYear() + '/' + (when.getMonth() + 1) + '/' + when.getDate() + ' ' + String(when.getHours()).padStart(2, '0') + ':' + String(when.getMinutes()).padStart(2, '0') + '\n' : '') +
            '解答 ' + answers + '問・学習日 ' + days + '日・ブックマーク ' + bookmarks + '件';
    }

    function restoreBackup(text) {
        var result = parseBackup(text);
        if (result.error) {
            showConfirm('復元できません', result.error, 'OK', false, function() {});
            document.getElementById('confirm-cancel').style.display = 'none';
            return;
        }
        var obj = result.backup;
        showConfirm('バックアップから復元', summarizeBackup(obj) + '\n\n今のデータはすべてこのバックアップに置き換えられます。', '復元する', true, function() {
            isResettingAll = true;  // stop the study timer from writing old data back
            clearInterval(timeSaveInterval);
            Object.keys(localStorage).forEach(function(k) { if (k.indexOf('jlpt') === 0) localStorage.removeItem(k); });
            Object.keys(obj.data).forEach(function(k) { localStorage.setItem(k, obj.data[k]); });
            localStorage.setItem('jlptLastBackup', String(Date.now()));
            location.reload();
        });
    }

