                var r = READINGS[id], texts = [];
                (r.pages || []).forEach(function(pg) { texts = texts.concat(pg.lines); });
                (r.bunkei || []).forEach(function(b) { texts = texts.concat(b.s); });
                if (r.kaiwa) r.kaiwa.lines.forEach(function(l) { texts.push(l[1]); });
