                    '<button class="aw-add' + (inList ? ' in' : '') + '" data-s="' + si + '" data-i="' + i + '" aria-label="' + escapeHtml(w[0]) + 'を単語帳に追加">' + (inList ? '✓' : '＋') + '</button></div>';
